import json,pathlib,math
R=pathlib.Path(__file__).resolve().parents[1];d=R/'reports'
final=json.loads((d/'final_evaluation.json').read_text());selected=json.loads((d/'selected.json').read_text());export=json.loads((d/'export_verification.json').read_text());browser=json.loads((d/'browser_check.json').read_text())
classes=final['class_order'];b=browser[0];reg=b['prediction']=='late_blight';deploy=final['passes_release_gate'] and export['compatible'] and reg
lines=['# Measured model-improvement results','',f"Selected checkpoint: epoch {selected['epoch']}. Training used validation-only selection; all test results below were obtained afterwards.",'','| Evaluation set | Images | Original accuracy | Candidate accuracy |','|---|---:|---:|---:|']
for source,result in final['test_results'].items():
 lines.append(f"| {source} test | {result['candidate']['n']} | {100*result['baseline']['accuracy']:.2f}% | {100*result['candidate']['accuracy']:.2f}% |")
lines+=['','These are dataset-specific measurements, not guaranteed field/drone accuracy. The PlantDoc test is small and its source labels have not been independently verified by an agronomist. The earlier locked test is now evaluated and must not be reused as an unseen holdout for future tuning.','',f"Known Plantix regression: browser predicts **{b['prediction']}** with scores "+', '.join(f'{name}: {100*p:.2f}%' for name,p in zip(classes,b['scores']))+'. The image was excluded from training and selection; one known regression case is not an independent accuracy estimate.','',f"TFLite export: {export['size_bytes']:,} bytes; top-class agreement {export['top1_agreement']:.1%} across {export['validation_samples']} validation images. Maximum probability difference {export['max_probability_delta']:.8f}.",'',f"Browser engine executed real inference on {len(browser)} smoke images. This tests runtime compatibility, not population accuracy.",'',f"Release checks: test comparison={final['passes_release_gate']}; conversion={export['compatible']}; reported Late-blight regression={reg}.",f"Recommended for experimental website update: {deploy}. No production reliability or 100% accuracy is claimed.",'','## Dataset coverage','Downloaded 3,164 images: the previously audited 2,902-image PlantVillage subset and all 262 matching PlantDoc source images. Seven PlantDoc images were quarantined. The model trained on 2,038 original images plus 190 PlantDoc images. Field training examples were repeated four times per epoch. Validation: 440 original + 37 field images. Test: 424 original + 28 field images. All retained training images were used each epoch; holdouts were never added to training.','', 'This is not a claim to use every online dataset or the entire 54,000-image multicrop PlantVillage repository. The original three-class audit covered 4,500 images, with unresolved identities/conflicts excluded. Mirrors and augmented copies were not counted as additional independent data.','', '## Remaining limitations','Only Early blight, Healthy and Late blight are disease outputs. Other diseases, non-tomato leaves, difficult lighting, blur and camera viewpoints can still be misclassified. The separate leaf screen reduces non-leaf inputs but does not certify species or all invalid inputs. Confidence scores are uncalibrated, not diagnostic certainty or lesion severity. More independently verified field images and a fresh external holdout are needed before claiming strong real-world reliability.','', '## Deployment status','No GitHub commit or live deployment has been made in this run. The prior connected GitHub integration rejected writes with HTTP 403. Any supplied website update must be uploaded by the repository owner.']
(d/'RESULTS.md').write_text('\n'.join(lines)+'\n')
s={'status':'completed','new_model_trained':True,'final_evaluation_completed':True,'website_updated':False,'all_online_datasets_used':False,'recommended_experimental_update':deploy,'known_regression_passed':reg}
(d/'run_status.json').write_text(json.dumps(s,indent=2));print(json.dumps(s))
